export function Interaction({
  actionType = "{{actionType}}",
  triggered = {{triggered}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa", textAlign: "center" }}>
      <div style={{ marginBottom: 6, textTransform: "capitalize" }}>User {actionType}s the star</div>
      <span style={{ fontSize: 28, color: triggered ? accent : "#24143033" }}>&#9733;</span>
      <div style={{ margin: "6px 0", opacity: .5 }}>&darr;</div>
      <div style={{ visibility: triggered ? "visible" : "hidden", fontWeight: 600, color: "#241430" }}>System responds: saved to favourites</div>
    </div>
  );
}
